// Custos cue parser. One place for the rules that the cue workflows each
// re-implement: who may give a cue, which text counts, and what a cue is.
// Plan: docs/plans/202610070939-cue-sigil-and-living-observation-plan.md
//
// A workflow calls it after a checkout:
//   const { parseComment } = require('./.github/scripts/cue-parser.js');
//   const r = parseComment(comment.body, {
//     association: comment.author_association, authorType: comment.user.type });
//
// Two forms are read, both only at the start of a line (up to three spaces in):
//   ^<navigo> [<conversation-id>] <cue words>     the caret form, case-insensitive
//   @claude <cue words>                           the older form, kept for now
// The caret form is the process cue. The older form stays during the transition.
//
// This module only reads text. It never labels, seals or merges.

// 'custos' addresses the workflows. 'omnes' addresses every contributor at once.
// 'cuncti' addresses the project as a whole: read it first, then add your own view.
const DEFAULT_NAMES = ['claude', 'chatgpt', 'gemini', 'perplexity', 'unexusi', 'custos', 'omnes', 'cuncti'];
const ACTIONS = ['recensio', 'probatio', 'lustratio', 'judicium', 'novissimum', 'cursus', 'emenda'];
// confirmanda and supplenda qualify emenda: the thing to amend is a claim to confirm, or a step the road lacks.
const MODIFIERS = ['prima', 'ultima', 'suprema', 'extrema', 'renovata', 'expeditus', 'confirmanda', 'supplenda'];
const VERBS = ['disponi', 'petitio', 'placet', 'finalize', 'check', 'concordance', 'sync-labels'];
// 3 to 12 characters after the dash, the same bound tools/session_id.sh check_own enforces
// (minted IDs are always 6; a hand-typed ID may be shorter or longer).
const ID_RE = /^(exp|set|con|oth)-[a-z0-9]{3,12}$/i;
// Matches both wordings: "Generated by" and "Generated with" (the latter is what
// Claude Code writes on pull request text). Case-insensitive, plain substring checks.
const FOOTERS = ['generated by [claude code]', 'generated with [claude code]'];
const hasFooter = (text) => FOOTERS.some((f) => String(text).toLowerCase().includes(f));

const cap = (w) => w.charAt(0).toUpperCase() + w.slice(1);

// Drop what is quoted rather than given: fenced code, inline code, > quotes
// and indented code. An unterminated fence runs to the end of the comment.
// The backtick is written \x60 so that tools that read this file as text do not
// mistake a regex for the start of a template string.
const FENCE_RE = /\x60\x60\x60[\s\S]*?(\x60\x60\x60|$)/g;
const TILDE_FENCE_RE = /~~~[\s\S]*?(~~~|$)/g;
const INLINE_CODE_RE = /\x60[^\x60\n]*\x60/g;

function dropCodeSpans(text) {
  return text
    .replace(FENCE_RE, '\n')
    .replace(TILDE_FENCE_RE, '\n')
    .replace(INLINE_CODE_RE, ' ');
}

const isQuoted = (line) => /^\s*>/.test(line);
const isIndentedCode = (line) => /^( {4,}|\t)/.test(line);

function strip(body) {
  const text = dropCodeSpans(body.replace(/\r\n?/g, '\n'));
  return text
    .split('\n')
    .filter((line) => !isQuoted(line) && !isIndentedCode(line))
    .join('\n');
}

const WHITESPACE_RE = /\s+/;
const TRAILING_PUNCT_RE = /[.,;:!?]+$/;
const stripPunct = (word) => word.replace(TRAILING_PUNCT_RE, '');

function tokenize(rest) {
  return rest.split(WHITESPACE_RE).map(stripPunct).filter(Boolean);
}

// An optional conversation id may come first.
function splitId(tokens) {
  if (tokens.length && ID_RE.test(tokens[0])) return { id: tokens[0].toLowerCase(), tokens: tokens.slice(1) };
  return { id: null, tokens };
}

const isKnown = (w) => ACTIONS.includes(w) || MODIFIERS.includes(w) || VERBS.includes(w);

const isVerbAlone = (actions, modifiers, verbs) =>
  verbs.length === 1 && actions.length === 0 && modifiers.length === 0;
const isLoneRenovata = (words) => words.length === 1 && words[0] === 'renovata';
const isOneAction = (actions, verbs) => actions.length === 1 && verbs.length === 0;

// What the known words mean together: a verb alone, a lone renovata, or one action with modifiers.
function shapeCue(id, words) {
  const actions = words.filter((w) => ACTIONS.includes(w));
  const modifiers = words.filter((w) => MODIFIERS.includes(w));
  const verbs = words.filter((w) => VERBS.includes(w));

  if (isVerbAlone(actions, modifiers, verbs)) {
    return { id, verb: verbs[0], canonical: verbs[0], modifiers: [], action: null };
  }
  // Renovata may stand alone: a request to refresh the current work (docs/latin-workflow-v2.md).
  if (isLoneRenovata(words)) {
    return { id, verb: null, action: null, modifiers: ['Renovata'], canonical: 'Renovata' };
  }
  if (isOneAction(actions, verbs)) {
    return {
      id, verb: null, action: cap(actions[0]),
      modifiers: modifiers.map(cap), canonical: words.map(cap).join(' '),
    };
  }
  return { id, error: 'ambiguous cue' };
}

// Read the words after the navigo name: an optional conversation id, then cue words.
function readWords(rest) {
  const { id, tokens } = splitId(tokenize(rest));
  if (!tokens.length) return { id, error: 'no cue words' };
  const words = tokens.map((t) => t.toLowerCase());
  const bad = words.filter((w) => !isKnown(w));
  if (bad.length) return { id, error: `unrecognized words: ${bad.join(', ')}` };
  return shapeCue(id, words);
}

const isEmpty = (body) => !body || !String(body).trim();
const isBot = (o) => o.authorType === 'Bot';
const notOwner = (o) => o.association !== undefined && !(o.allowed || ['OWNER']).includes(o.association);

// Why a whole comment is not read at all, in the order the reasons are checked.
const SKIP_RULES = [
  ['empty', (c) => isEmpty(c.body)],
  ['bot', (c) => isBot(c.opts)],
  ['not owner', (c) => notOwner(c.opts)],
  ['footer', (c) => hasFooter(c.body)],
];

// The first reason a comment is skipped, or null when it is read.
function skipReason(body, opts) {
  const hit = SKIP_RULES.find(([, test]) => test({ body, opts }));
  return hit ? hit[0] : null;
}

const CARET_RE = /^ {0,3}\^([A-Za-z][A-Za-z0-9_-]*)(?![A-Za-z0-9_-])(.*)$/;
const AT_RE = /^ {0,3}@(claude)(?![A-Za-z0-9_-])(.*)$/i;

function matchLine(line) {
  const caret = line.match(CARET_RE);
  const at = !caret && line.match(AT_RE);
  const m = caret || at;
  return m ? { sigil: caret ? '^' : '@', navigo: m[1].toLowerCase(), rest: m[2] } : null;
}

// One line -> null (not a cue), { rejected } or { cue }.
function readLine(line, number, names) {
  const m = matchLine(line);
  if (!m) return null;
  const { sigil, navigo } = m;
  if (!names.includes(navigo)) return { rejected: { line: number, sigil, navigo, reason: 'unknown navigo' } };
  const read = readWords(m.rest);
  if (read.error) return { rejected: { line: number, sigil, navigo, reason: read.error } };
  return {
    cue: {
      line: number, sigil, navigo, id: read.id,
      action: read.action, modifiers: read.modifiers, verb: read.verb, canonical: read.canonical,
    },
  };
}

function parseComment(body, opts) {
  const o = opts || {};
  const names = (o.names || DEFAULT_NAMES).map((n) => n.toLowerCase());
  const out = { cues: [], rejected: [], skipped: skipReason(body, o) };
  if (out.skipped) return out;

  strip(String(body)).split('\n').forEach((line, i) => {
    const r = readLine(line, i + 1, names);
    if (r?.cue) out.cues.push(r.cue);
    if (r?.rejected) out.rejected.push(r.rejected);
  });
  return out;
}

module.exports = { parseComment, strip, DEFAULT_NAMES, ACTIONS, MODIFIERS, VERBS };
